"""Rank of the D-module generated by the target-sector holomorphic 2-form s = Res(rho Omega/G) on S3,
over the (c1,c2) base: span of nabla^alpha s, |alpha| <= m, in Griffiths normal form at a point."""
import sympy as sp, pickle, sys, itertools
from flint import fmpq_mat, fmpq
rho, tau, x, v, c1, c2, t = sp.symbols('rho tau x v c1 c2 t')
D = pickle.load(open('variation.pkl', 'rb'))
C1, C2 = (int(sys.argv[1]), int(sys.argv[2])) if len(sys.argv) > 2 else (2, 3)
MAXORD = int(sys.argv[3]) if len(sys.argv) > 3 else 4
def as_t_sym(expr, vpow): return sp.expand(sp.expand(expr / v**vpow).subs(v, t**sp.Rational(1, 6)))
def form(F_t, deg): return sp.expand(rho**deg * F_t.subs(t, (tau/rho)**3))
As, Bs = as_t_sym(D['A'], 0), as_t_sym(D['B'], 0)
Gsym = -form(As, 12)*x - form(Bs, 18)          # G = y^2 + Gsym; only Gsym depends on c
sub = {c1: C1, c2: C2}
def dG(beta):                                   # d^beta G / dc^beta at the point
    e = Gsym
    for i, n in enumerate(beta):
        for _ in range(n): e = sp.diff(e, (c1, c2)[i])
    return sp.expand(e.subs(sub))
G0 = sp.expand(Gsym.subs(sub))
Jg = [(sp.expand(sp.diff(G0, rho)), 17), (sp.expand(sp.diff(G0, tau)), 17), (sp.expand(sp.diff(G0, x)), 12)]
VARS = (rho, tau, x)
# formal derivation: terms are dict {(k, frozenset-monomial in g-symbols as tuple of betas): coefficient-poly in rho,tau,x}
gsyms = {}
def g(beta):
    if beta not in gsyms: gsyms[beta] = sp.Symbol('g_%d_%d' % beta)
    return gsyms[beta]
def nabla(terms, i):
    out = {}
    def add(k, expr):
        out[k] = sp.expand(out.get(k, 0) + expr)
    for k, Q in terms.items():
        # d/dc_i of Q (chain rule on g symbols)
        dQ = 0
        for beta, sym in list(gsyms.items()):
            if Q.has(sym):
                nb = tuple(beta[j] + (1 if j == i else 0) for j in range(2))
                dQ += sp.diff(Q, sym)*g(nb)
        if dQ != 0: add(k, dQ)
        add(k + 1, -k*Q*g(tuple(1 if j == i else 0 for j in range(2))))
    return {k: e for k, e in out.items() if e != 0}
# ---- Griffiths reduction to normal form at the point ----
def monos(d): return [(i, d - 6*kk - i, kk) for kk in range(d//6 + 1) for i in range(d - 6*kk + 1)] if d >= 0 else []
def mono(e): return rho**e[0]*tau**e[1]*x**e[2]
cache = {}
def setup(d):
    if d in cache: return cache[d]
    rows = {m: r for r, m in enumerate(monos(d))}
    cols, meta = [], []
    for jg, (gpoly, gd) in enumerate(Jg):
        for e in monos(d - gd):
            cols.append(sp.Poly(sp.expand(gpoly*mono(e)), *VARS)); meta.append((jg, e))
    n = len(rows); M = fmpq_mat(n, len(cols))
    for j, p in enumerate(cols):
        for mon, cf in p.terms(): M[rows[mon], j] = fmpq(int(sp.numer(cf)), int(sp.denom(cf)))
    # choose normal-form monomials: greedy complement of column space
    rk = M.rank(); basis = []
    cur = M
    for m in monos(d):
        if len(basis) == n - rk: break
        ext = fmpq_mat(n, len(cols) + len(basis) + 1)
        for r in range(n):
            for j in range(len(cols)): ext[r, j] = M[r, j]
        for bi, bm in enumerate(basis + [m]): ext[rows[bm], len(cols) + bi] = 1
        if ext.rank() == rk + len(basis) + 1: basis.append(m)
    cache[d] = (rows, cols, meta, M, basis)
    return cache[d]
def reduce(Q, k):
    """Res(Q Omega/G^k) -> dict {(deg, basis monomial): coeff} normal form."""
    out = {}
    while k >= 1 and Q != 0:
        d = 18*k - 17
        rows, cols, meta, M, basis = setup(d)
        n = len(rows)
        # solve Q = sum A_j dG_j + sum b_m m  (b on normal-form monomials)
        A = fmpq_mat(n, len(cols) + len(basis))
        for r in range(n):
            for j in range(len(cols)): A[r, j] = M[r, j]
        for bi, bm in enumerate(basis): A[rows[bm], len(cols) + bi] = 1
        bvec = fmpq_mat(n, 1)
        for mon, cf in sp.Poly(Q, *VARS).terms(): bvec[rows[mon], 0] = fmpq(int(sp.numer(cf)), int(sp.denom(cf)))
        sol = A.solve(bvec) if A.nrows() == A.ncols() else None
        if sol is None:
            # least-squares-free: use rref on augmented system
            aug = fmpq_mat(n, A.ncols() + 1)
            for r in range(n):
                for j in range(A.ncols()): aug[r, j] = A[r, j]
                aug[r, A.ncols()] = bvec[r, 0]
            R, rnk = aug.rref()
            sol = [fmpq(0)]*A.ncols()
            for r in range(rnk):
                piv = next(j for j in range(A.ncols() + 1) if R[r, j] != 0)
                assert piv < A.ncols(), 'inconsistent'
                sol[piv] = R[r, A.ncols()]
        else:
            sol = [sol[j, 0] for j in range(A.ncols())]
        for bi, bm in enumerate(basis):
            if sol[len(cols) + bi] != 0: out[(d, bm)] = out.get((d, bm), 0) + sol[len(cols) + bi]
        if k == 1: break
        Ajs = [0, 0, 0]
        for j, (jg, e) in enumerate(meta):
            if sol[j] != 0: Ajs[jg] += sp.Rational(int(sol[j].p), int(sol[j].q))*mono(e)
        Q = sp.expand(sum(sp.diff(Ajs[jj], VARS[jj]) for jj in range(3)) / (k - 1))
        k -= 1
    return out
def evaluate(terms):
    vec = {}
    for k, Q in terms.items():
        Qn = sp.expand(Q.subs({sym: dG(beta) for beta, sym in gsyms.items()}))
        for key, val in reduce(Qn, k).items(): vec[key] = vec.get(key, 0) + val
    return vec
# ---- run ----
s = {1: rho}
layer = {(): s}
vecs = [evaluate(s)]
keys = set(vecs[0])
for order in range(1, MAXORD + 1):
    new = {}
    for alpha, terms in layer.items():
        for i in (0, 1):
            a2 = tuple(sorted(alpha + (i,)))
            if a2 not in new: new[a2] = nabla(terms, i)
    layer = new
    for alpha, terms in layer.items():
        vecs.append(evaluate(terms))
    keys = sorted({k for vv in vecs for k in vv})
    Mv = fmpq_mat(len(vecs), len(keys))
    for r, vv in enumerate(vecs):
        for j, kk in enumerate(keys):
            if kk in vv: Mv[r, j] = vv[kk]
    print(f'(c1,c2)=({C1},{C2}) order <= {order}: {len(vecs)} derivatives, rank of span = {Mv.rank()}', flush=True)
